import {pool,makeState,box,active,point,concentration,immersed,clipToVessel,physicsFor,updateParents,EPS} from './measurement-common.js';
export * from './measurement-common.js';
export const CELL={E0:1.10,nernst:.05916/2,F:96485,zincMass:65.38,copperMass:63.546,load:100,internal:70};
export function createState(){const s=makeState('voltaic',{left:pool('left','Zinc sulfate · 0.100 M',350,429,100,{Zn:.01,sulfate:.01}),right:pool('right','Copper(II) sulfate · 0.100 M',570,429,100,{Cu:.01,sulfate:.01}),water:pool('water','Deionised water',900,429,500,{},600),waste:pool('waste','Waste beaker',100,100,0,{},1000),
 zinc:{id:'zinc',name:'Zinc strip',kind:'metalStrip',metal:'Zn',metalMoles:.03,plated:0,x:220,y:100,angle:0,collision:[box(0,45,18,90)]},copper:{id:'copper',name:'Copper strip',kind:'metalStrip',metal:'Cu',metalMoles:.03,plated:0,x:320,y:100,angle:0,collision:[box(0,45,18,90)]},
 bridge:{id:'bridge',name:'KNO₃ gel salt bridge',kind:'saltBridge',x:450,y:100,angle:0,K:.02,nitrate:.02,targets:null,collision:[box(0,6,200,12),box(-94,43,12,76),box(94,43,12,76)]},
 meter:{id:'meter',name:'Voltmeter / 100 Ω load',kind:'voltmeter',x:755,y:445,angle:0,loaded:false,collision:[box(0,40,145,80)],mass:3}});Object.assign(s,{extent:0,displacement:0,charge:0});return s;}
export function clip(s,id){return ['zinc','copper'].includes(id)&&Boolean(clipToVessel(s,id,0));}
export function fitBridge(s){const b=s.items.bridge;if(s.phase!=='working'||!active(b))return false;const ends=[point(b,-94,80),point(b,94,80)],v=ends.map(p=>Object.values(s.items).filter(o=>active(o)&&o.kind==='beaker'&&o.water>5&&Math.abs(o.x-p.x)<65&&Math.abs(o.y-p.y)<110).sort((a,c)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(c.x-p.x,c.y-p.y))[0]);if(!v[0]||!v[1]||v[0]===v[1])return false;b.targets=v.map(o=>o.id);b.parent=v[0].id;b.offset={x:(v[1].x-v[0].x)/2,y:-35};updateParents(s);physicsFor(s).sync();return true;}
export function bridged(s,a,b){const t=s.items.bridge;if(!active(t)||!t.targets||t.K<=EPS||t.nitrate<=EPS)return false;const ends=[point(t,-94,80),point(t,94,80)];return t.targets.includes(a.id)&&t.targets.includes(b.id)&&t.targets.every((id,i)=>{const o=s.items[id];return active(o)&&o.water>5&&Math.abs(o.angle||0)<20&&Math.abs(o.x-ends[i].x)<65&&ends[i].y>=o.y+86-72*Math.min(1,o.water/o.capacity)&&ends[i].y<=o.y+100;});}
export function reading(s){const z=s.items.zinc,c=s.items.copper,m=s.items.meter,a=immersed(s,'zinc'),b=immersed(s,'copper');const invalid=status=>({voltage:null,current:0,emf:null,status,operating:false});if(!active(m))return invalid('Meter stored.');if(!active(z)||!active(c)||!a||!b||a===b)return invalid('Immerse the zinc and copper strips in separate half-cells.');if(a.solutes.Zn<=EPS||b.solutes.Cu<=EPS||a.solutes.Cu>1e-8||b.solutes.Zn>1e-8||z.metalMoles<=EPS)return invalid('Check the half-cell solutions and remaining metals. Mixed/wrong half-cells are not the specified Zn/Zn²⁺ and Cu²⁺/Cu couples.');
 const red=s.leads.red,black=s.leads.black;if(!['zinc','copper'].includes(red)||!['zinc','copper'].includes(black))return invalid('Connect both meter leads to electrode terminals.');if(red===black)return{voltage:0,current:0,emf:0,status:'Both leads contact the same strip.',operating:false};const emf=CELL.E0-CELL.nernst*Math.log10(concentration(a,'Zn')/concentration(b,'Cu')),sign=red==='copper'?1:-1,bridge=bridged(s,a,b),i=m.loaded&&bridge?Math.max(0,emf)/(CELL.load+CELL.internal):0,voltage=m.loaded?i*CELL.load:emf;
 return{voltage:sign*voltage,current:sign*i,emf,operating:i>EPS,anode:a.id,cathode:b.id,status:!bridge?'Salt bridge open · voltage indication alone does not establish a working cell.':m.loaded?'Discharging · electrons travel Zn → Cu; the displayed sign follows the leads.':'High-resistance voltmeter · near-open-circuit measurement.'};}
export function stepChemistry(s,dt){if(s.phase!=='working'||!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,60);s.time+=dt;
 // Zinc placed directly in a Cu²⁺ solution also displaces copper without wires.
 const z=s.items.zinc,contact=immersed(s,'zinc');if(active(z)&&contact&&contact.solutes.Cu>EPS&&z.metalMoles>EPS){const n=Math.min(contact.solutes.Cu,z.metalMoles,.00002*dt);contact.solutes.Cu-=n;contact.solutes.Zn+=n;z.metalMoles-=n;z.plated+=n;s.displacement+=n;}
 const r=reading(s);if(!r.operating)return;const a=s.items[r.anode],b=s.items[r.cathode],bridge=s.items.bridge,c=s.items.copper,n=Math.min(Math.abs(r.current)*dt/(2*CELL.F),z.metalMoles,b.solutes.Cu,bridge.K/2,bridge.nitrate/2);z.metalMoles-=n;a.solutes.Zn+=n;b.solutes.Cu-=n;c.plated+=n;bridge.K-=2*n;bridge.nitrate-=2*n;b.solutes.K+=2*n;a.solutes.nitrate+=2*n;s.extent+=n;s.charge+=2*n*CELL.F;
}
export function record(s){if(s.phase!=='working')return null;const r=reading(s);if(r.voltage===null)return null;const row={time:s.time,voltage:Number(r.voltage.toFixed(3)),current:Number((r.current*1000).toFixed(3)),charge:s.charge,zincMass:s.items.zinc.metalMoles*CELL.zincMass,copperGain:s.items.copper.plated*CELL.copperMass,loaded:s.items.meter.loaded,bridge:r.anode?bridged(s,s.items[r.anode],s.items[r.cathode]):false};s.records.push(row);return row;}
export function metalTotals(s){const pools=[...Object.values(s.items),...s.spills].filter(o=>o.solutes);return{Zn:s.items.zinc.metalMoles+pools.reduce((n,o)=>n+o.solutes.Zn,0),Cu:s.items.copper.metalMoles+s.items.copper.plated+s.items.zinc.plated+pools.reduce((n,o)=>n+o.solutes.Cu,0),K:s.items.bridge.K+pools.reduce((n,o)=>n+o.solutes.K,0),nitrate:s.items.bridge.nitrate+pools.reduce((n,o)=>n+o.solutes.nitrate,0)};}
